import{_ as a,a0 as n,w as i,s as l,ao as d,I as p,x as t,a1 as s,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何使用物聯網設備來確保兒童安全？ | LCTT x X-CMD","titleTemplate":false,"description":"如何使用物聯網設備來確保兒童安全？ | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用物聯網設備來確保兒童安全？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用物聯網設備來確保兒童安全？ | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191011 How to use IoT devices to keep children safe","title":"如何使用物聯網設備來確保兒童安全？","tag":"201910","desc":""},"relativePath":"201910/20191011 How to use IoT devices to keep children safe.md","filePath":"[post].md"}'),u={name:"201910/20191011 How to use IoT devices to keep children safe.md"};function f(T,e,m,h,x,C){const o=n("Link");return i(),l("div",null,[e[15]||(e[15]=d('<h1 id="如何使用物聯網設備來確保兒童安全" tabindex="-1">如何使用物聯網設備來確保兒童安全？ <a class="header-anchor" href="#如何使用物聯網設備來確保兒童安全" aria-label="Permalink to “如何使用物聯網設備來確保兒童安全？”">​</a></h1><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/10/Visual-Internet-of-things_EB-May18.jpg?resize=696%2C507&amp;ssl=1" alt="" title="Visual Internet of things_EB May18"></p><p>IoT （物聯網）設備正在迅速改變我們的生活。這些設備無處不在，從我們的家庭到其它行業。根據一些預測數據，到 2020 年，將會有 100 億個 IoT 設備。到 2025 年，該數量將增長到 220 億。目前，物聯網已經在很多領域得到了應用，包括智能家居、工業生產過程、農業甚至醫療保健領域。伴隨着如此廣泛的應用，物聯網顯然已經成為近年來的熱門話題之一。</p><p>多種因素促成了物聯網設備在多個學科的爆炸式增長。這其中包括低成本處理器和無線連接的的可用性，以及開源平台的信息交流推動了物聯網領域的創新。與傳統的應用程序開發相比，物聯網設備的開發成指數級增長，因為它的資源是開源的。</p><p>在解釋如何使用物聯網設備來保護兒童之前，必須對物聯網技術有基本的瞭解。</p><h3 id="iot-設備是什麼" tabindex="-1">IoT 設備是什麼？ <a class="header-anchor" href="#iot-設備是什麼" aria-label="Permalink to “IoT 設備是什麼？”">​</a></h3><p>IoT 設備是指那些在沒有人類參與的情況下彼此之間可以通信的設備。因此，許多專家並不將智能手機和計算機視為物聯網設備。此外，物聯網設備必須能夠收集數據並且能將收集到的數據傳送到其他設備或雲端進行處理。</p><p>然而，在某些領域中，我們需要探索物聯網的潛力。兒童往往是脆弱的，他們很容易成為犯罪分子和其他蓄意傷害者的目標。無論在物理世界還是數字世界中，兒童都很容易面臨犯罪的威脅。因為父母不能始終親自到場保護孩子；這就是為什麼需要監視工具了。</p><p>除了適用於兒童的可穿戴設備外，還有許多父母監視應用程序，例如 Xnspy，可實時監控兒童並提供信息的實時更新。這些工具可確保兒童安全。可穿戴設備確保兒童身體上的安全性，而家長監控應用可確保兒童的上網安全。</p><p>由於越來越多的孩子花費時間在智能手機上，毫無意外地，他們也就成為詐騙分子的主要目標。此外，由於戀童癖、網絡自誇和其他犯罪在網絡上的盛行，兒童也有可能成為網絡欺凌的目標。</p><p>這些解決方案夠嗎？我們需要找到物聯網解決方案，以確保孩子們在網上和線下的安全。在當代，我們如何確保孩子的安全？我們需要提出創新的解決方案。 物聯網可以幫助保護孩子在學校和家裏的安全。</p><h3 id="物聯網的潛力" tabindex="-1">物聯網的潛力 <a class="header-anchor" href="#物聯網的潛力" aria-label="Permalink to “物聯網的潛力”">​</a></h3><p>物聯網設備提供的好處很多。舉例來説，父母可以遠程監控自己的孩子，而又不會顯得太霸道。因此，兒童在擁有安全環境的同時也會有空間和自由讓自己變得獨立。</p><p>而且，父母也不必在為孩子的安全而擔憂。物聯網設備可以提供 7x24 小時的信息更新。像 Xnspy 之類的監視應用程序在提供有關孩子的智能手機活動信息方面更進了一步。隨着物聯網設備變得越來越複雜，擁有更長使用壽命的電池只是一個時間問題。諸如位置跟蹤器之類的物聯網設備可以提供有關孩子下落的準確詳細信息，所以父母不必擔心。</p><p>雖然可穿戴設備已經非常好了，但在確保兒童安全方面，這些通常還遠遠不夠。因此，要為兒童提供安全的環境，我們還需要其他方法。許多事件表明，兒童在學校比其他任何公共場所都容易受到攻擊。因此，學校需要採取安全措施，以確保兒童和教師的安全。在這一點上，物聯網設備可用於檢測潛在威脅並採取必要的措施來防止攻擊。威脅檢測系統包括攝像頭。系統一旦檢測到威脅，便可以通知當局，如一些執法機構和醫院。智能鎖等設備可用於封鎖學校（包括教室），來保護兒童。除此之外，還可以告知父母其孩子的安全，並立即收到有關威脅的警報。這將需要實施無線技術，例如 Wi-Fi 和傳感器。因此，學校需要制定專門用於提供教室安全性的預算。</p><p>智能家居實現拍手關燈，也可以讓你的家庭助手幫你關燈。同樣，物聯網設備也可用在屋內來保護兒童。在家裏，物聯網設備（例如攝像頭）為父母在照顧孩子時提供 100％ 的可見性。當父母不在家裏時，可以使用攝像頭和其他傳感器檢測是否發生了可疑活動。其他設備（例如連接到這些傳感器的智能鎖）可以鎖門和窗，以確保孩子們的安全。</p><p>同樣，可以引入許多物聯網解決方案來確保孩子的安全。</p><h3 id="有多好就有多壞" tabindex="-1">有多好就有多壞 <a class="header-anchor" href="#有多好就有多壞" aria-label="Permalink to “有多好就有多壞”">​</a></h3><p>物聯網設備中的傳感器會創建大量數據。數據的安全性是至關重要的一個因素。收集的有關孩子的數據如果落入不法分子手中會存在危險。因此，需要採取預防措施。IoT 設備中泄露的任何數據都可用於確定行為模式。因此，必須對提供不違反用户隱私的安全物聯網解決方案投入資金。</p><p>IoT 設備通常連接到 Wi-Fi，用於設備之間傳輸數據。未加密數據的不安全網絡會帶來某些風險。這樣的網絡很容易被竊聽。黑客可以使用此類網點來入侵系統。他們還可以將惡意軟件引入系統，從而使系統變得脆弱、易受攻擊。此外，對設備和公共網絡（例如學校的網絡）的網絡攻擊可能導致數據泄露和私有數據盜用。 因此，在實施用於保護兒童的物聯網解決方案時，保護網絡和物聯網設備的總體計劃必須生效。</p><p>物聯網設備保護兒童在學校和家裏的安全的潛力尚未發現有什麼創新。我們需要付出更多努力來保護連接 IoT 設備的網絡安全。此外，物聯網設備生成的數據可能落入不法分子手中，從而造成更多麻煩。因此，這是物聯網安全至關重要的一個領域。</p><hr>',22)),p("p",null,[e[1]||(e[1]=t("via: ",-1)),s(o,{href:"https://opensourceforu.com/2019/10/how-to-use-iot-devices-to-keep-children-safe/"},{default:r(()=>[...e[0]||(e[0]=[t("https://opensourceforu.com/2019/10/how-to-use-iot-devices-to-keep-children-safe/",-1)])]),_:1})]),p("p",null,[e[6]||(e[6]=t("作者：",-1)),s(o,{href:"https://opensourceforu.com/author/andrew-carroll/"},{default:r(()=>[...e[2]||(e[2]=[t("Andrew Carroll",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:r(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),s(o,{href:"https://github.com/Morisun029"},{default:r(()=>[...e[4]||(e[4]=[t("Morisun029",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:r(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),s(o,{href:"https://linux.cn/"},{default:r(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const g=a(u,[["render",f]]);export{w as __pageData,g as default};
